166:     // Prepend newest first (stored array keeps newest at index 0, so iterate in reverse)
167:     for (let i = stored.length - 1; i >= 0; i -= 1) {
168:       const card = createReviewCardElement(stored[i]);
169:       reviewsGrid.prepend(card);
