173:   function updateSummaryMetrics() {
174:     if (!reviewsGrid) return;
175:     const allCards = Array.from(reviewsGrid.querySelectorAll(".review-card"));
176:     const count = allCards.length;
177:     const sum = allCards.reduce(function (acc, card) {
178:       return acc + (Number(card.dataset.rating) || 0);
179:     }, 0);
180:     const avg = count ? (sum / count).toFixed(1) : "0.0";
181: 
182:     if (avgRatingValue) avgRatingValue.textContent = avg;
183:     if (totalReviewsCount) totalReviewsCount.textContent = String(count);
184:   }
