186:   function applyReviewFilters() {
187:     if (!reviewsGrid) return;
188:     const allCards = Array.from(reviewsGrid.querySelectorAll(".review-card"));
189: 
190:     occasionTabs.forEach(function (tab) {
191:       const isSelected = (tab.dataset.occasion || "all") === activeOccasion;
192:       tab.classList.toggle("is-active", isSelected);
193:       tab.setAttribute("aria-selected", String(isSelected));
194:     });
195: 
196:     let visibleCount = 0;
197:     allCards.forEach(function (card) {
198:       const cardOccasion = card.dataset.occasion || "";
199:       const cardRating = Number(card.dataset.rating) || 0;
200: 
201:       const matchesOccasion =
202:         activeOccasion === "all" || cardOccasion === activeOccasion;
203: 
204:       let matchesRating = true;
205:       if (activeRating === "5") {
206:         matchesRating = cardRating === 5;
207:       } else if (activeRating === "4") {
208:         matchesRating = cardRating >= 4;
209:       }
210: 
211:       const visible = matchesOccasion && matchesRating;
212:       card.hidden = !visible;
213:       if (visible) visibleCount += 1;
214:     });
215: 
216:     if (reviewsStatus) {
217:       reviewsStatus.textContent =
218:         visibleCount === 1
219:           ? "Showing 1 guest review"
220:           : "Showing " + visibleCount + " guest reviews";
221:     }
222:     if (reviewsEmpty) {
223:       reviewsEmpty.hidden = visibleCount > 0;
224:     }
225:   }
226: 
227:   occasionTabs.forEach(function (tab) {
228:     tab.addEventListener("click", function () {
229:       activeOccasion = tab.dataset.occasion || "all";
230:       applyReviewFilters();
231:     });
232:   });
