364:   function updateItemQty(id, delta) {
365:     const cart = readCart();
366:     const updated = cart
367:       .map(function (entry) {
368:         if (entry.id !== id) return entry;
369:         return {
370:           id: entry.id,
371:           title: entry.title,
372:           price: entry.price,
373:           qty: (Number(entry.qty) || 1) + delta
374:         };
375:       })
376:       .filter(function (entry) {
377:         return entry.qty > 0;
378:       });
379: 
380:     writeCart(updated);
381:   }
