484:   function closeCartDrawer() {
485:     if (!cartDrawer || !cartBackdrop || cartDrawer.hidden) return;
486:     cartDrawer.hidden = true;
487:     cartBackdrop.hidden = true;
488:     if (cartTrigger) cartTrigger.setAttribute("aria-expanded", "false");
489:     document.body.style.overflow = "";
