   ========================================================================== */

:root {
  --bg-obsidian: #0a0807;
  --bg-espresso: #120e0c;
  --bg-surface: #191310;
  --bg-elevated: #221a15;

  --accent-gold: #d4af37;
  --accent-champagne: #e7c68e;
  --accent-gold-soft: rgba(212, 175, 55, 0.14);

  --text-primary: #f6f1eb;
  --text-secondary: #c7bdb3;
  --text-muted: #93877b;
  --text-error: #f28b82;

  --border-subtle: rgba(231, 198, 142, 0.16);
  --border-strong: rgba(212, 175, 55, 0.45);

  --font-display: "Cormorant Garamond", Georgia, serif;
  --font-sans: "Plus Jakarta Sans", -apple-system, BlinkMacSystemFont, sans-serif;

  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 18px;
  --shadow-luxury: 0 20px 50px rgba(0, 0, 0, 0.6);
  --transition-fast: 180ms cubic-bezier(0.22, 1, 0.36, 1);
  --transition-med: 280ms cubic-bezier(0.22, 1, 0.36, 1);
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  background-color: var(--bg-obsidian);
  background-image:
    radial-gradient(circle at 15% 10%, rgba(212, 175, 55, 0.06), transparent 40%),
    radial-gradient(circle at 85% 25%, rgba(231, 198, 142, 0.04), transparent 45%);
  color: var(--text-primary);
  font-family: var(--font-sans);
  font-size: 16px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

img {
  display: block;
  max-width: 100%;
}

a {
  color: inherit;
  text-decoration: none;
}

button,
input,
select,
textarea {
  font-family: inherit;
}

button {
  cursor: pointer;
}

:focus-visible {
  outline: 2px solid var(--accent-gold);
  outline-offset: 3px;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.skip-link {
  position: absolute;
  left: -9999px;
  top: 0;
  background: var(--accent-gold);
  color: var(--bg-obsidian);
  padding: 0.75rem 1.25rem;
  font-weight: 600;
  z-index: 1000;
}

.skip-link:focus {
  left: 1rem;
  top: 1rem;
  border-radius: var(--radius-sm);
}

.container {
  width: min(1240px, 92vw);
  margin-inline: auto;
}

/* Header & Navigation
   ========================================================================== */
.site-header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(10, 8, 7, 0.9);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border-subtle);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.25rem;
  min-height: 76px;
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 0.75rem;
  flex-shrink: 0;
}

.brand-mark {
  display: grid;
  place-items: center;
  width: 40px;
  height: 40px;
  border-radius: 50%;
  border: 1px solid var(--accent-gold);
  background: var(--bg-surface);
  color: var(--accent-champagne);
  font-family: var(--font-display);
  font-size: 1.45rem;
  font-weight: 700;
}

.brand-text {
  display: flex;
  flex-direction: column;
  line-height: 1.15;
}

.brand-name {
  font-family: var(--font-display);
  font-size: 1.45rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  color: var(--text-primary);
}

.brand-loc {
  font-size: 0.72rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--accent-champagne);
}

.primary-nav {
  margin-inline: auto;
}

.nav-list {
  display: flex;
  align-items: center;
  gap: 1.15rem;
  list-style: none;
  margin: 0;
  padding: 0;
}

.nav-link {
  position: relative;
  font-size: 0.88rem;
  font-weight: 500;
  color: var(--text-secondary);
  padding: 0.35rem 0;
  transition: color var(--transition-fast);
  white-space: nowrap;
}

.nav-link:hover,
.nav-link.is-active {
  color: var(--accent-champagne);
}

.nav-link.is-active::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: -2px;
  height: 2px;
  background: linear-gradient(90deg, var(--accent-gold), var(--accent-champagne));
  border-radius: 2px;
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.cart-trigger {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.52rem 0.95rem;
  border-radius: 999px;
  border: 1px solid var(--border-strong);
  background: var(--bg-surface);
  color: var(--text-primary);
  font-size: 0.85rem;
  font-weight: 600;
  transition: background-color var(--transition-fast), border-color var(--transition-fast), transform var(--transition-fast);
}

.cart-trigger:hover {
  background: var(--bg-elevated);
  border-color: var(--accent-gold);
  transform: translateY(-1px);
}

.icon-cart {
  width: 18px;
  height: 18px;
  color: var(--accent-champagne);
}

.cart-badge {
  display: inline-grid;
  place-items: center;
  min-width: 22px;
  height: 22px;
  padding-inline: 0.35rem;
  border-radius: 999px;
  background: var(--accent-gold);
  color: var(--bg-obsidian);
  font-size: 0.75rem;
  font-weight: 700;
}

.nav-toggle {
  display: none;
  flex-direction: column;
  justify-content: center;
  gap: 5px;
  width: 42px;
  height: 42px;
  padding: 8px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-subtle);
  background: var(--bg-surface);
}

.nav-toggle-bar {
  display: block;
  width: 100%;
  height: 2px;
  background: var(--accent-champagne);
  border-radius: 2px;
}

/* Hero Section
   ========================================================================== */
.catering-hero {
  padding: 4.25rem 0 3rem;
  background: linear-gradient(180deg, var(--bg-espresso) 0%, var(--bg-obsidian) 100%);
  border-bottom: 1px solid var(--border-subtle);
  text-align: center;
}

.hero-content {
  max-width: 780px;
}

.eyebrow {
  margin: 0 0 0.75rem;
  font-size: 0.78rem;
  font-weight: 600;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--accent-gold);
}

.catering-hero h1 {
  margin: 0 0 1rem;
  font-family: var(--font-display);
  font-size: clamp(2.4rem, 5vw, 3.8rem);
  font-weight: 600;
  line-height: 1.08;
  color: var(--text-primary);
}

.hero-subtitle {
  margin: 0 auto;
  max-width: 62ch;
  color: var(--text-secondary);
  font-size: 1.02rem;
}

.hero-metrics {
  display: inline-grid;
  grid-template-columns: repeat(3, minmax(130px, 1fr));
  gap: 1rem;
  margin-top: 2rem;
  padding: 1rem 1.5rem;
  border-radius: var(--radius-md);
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
}

.metric-pill {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.15rem;
}

.metric-value {
  font-family: var(--font-display);
  font-size: 1.8rem;
  font-weight: 700;
  line-height: 1;
  color: var(--accent-champagne);
}

.metric-label {
  font-size: 0.74rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-muted);
}

/* Shared Section Headers & Buttons
   ========================================================================== */
.section-header {
  max-width: 680px;
  margin-bottom: 2.25rem;
}

.section-header h2 {
  margin: 0 0 0.65rem;
  font-family: var(--font-display);
  font-size: clamp(1.9rem, 3.4vw, 2.7rem);
  font-weight: 600;
  line-height: 1.12;
  color: var(--text-primary);
}

.section-lead {
  margin: 0;
  color: var(--text-secondary);
  font-size: 0.98rem;
}

.card-tag {
  display: inline-block;
  font-size: 0.72rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--accent-champagne);
  background: var(--accent-gold-soft);
  padding: 0.25rem 0.6rem;
  border-radius: 999px;
}

.btn-gold,
.btn-outline {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.68rem 1.25rem;
  border-radius: var(--radius-sm);
  font-size: 0.88rem;
  font-weight: 600;
  transition: all var(--transition-fast);
  text-align: center;
}

.btn-gold {
  border: 1px solid transparent;
  background: linear-gradient(135deg, var(--accent-gold), var(--accent-champagne));
  color: var(--bg-obsidian);
}

.btn-gold:hover {
  filter: brightness(1.08);
  transform: translateY(-1px);
}

.btn-outline {
  border: 1px solid var(--border-strong);
  background: transparent;
  color: var(--accent-champagne);
}

.btn-outline:hover {
  background: var(--accent-gold-soft);
  border-color: var(--accent-gold);
}

/* Catering Packages Section
   ========================================================================== */
.packages-section {
  padding: 4rem 0 3rem;
}

.packages-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1.5rem;
}

.package-card {
  display: flex;
  flex-direction: column;
  padding: 1.85rem;
  border-radius: var(--radius-lg);
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  transition: transform var(--transition-med), border-color var(--transition-med), box-shadow var(--transition-med);
}

.package-card:hover {
  transform: translateY(-4px);
  border-color: var(--border-strong);
  box-shadow: var(--shadow-luxury);
}

.package-card.is-featured,
.package-card.is-selected {
  border-color: var(--accent-gold);
  background: linear-gradient(180deg, rgba(212, 175, 55, 0.08), var(--bg-surface) 45%);
}

.package-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  margin-bottom: 1rem;
}

.package-guests {
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--text-muted);
}

.package-title {
  margin: 0 0 0.5rem;
  font-family: var(--font-display);
  font-size: 1.8rem;
  font-weight: 600;
  line-height: 1.15;
  color: var(--text-primary);
}

.package-price {
  margin: 0 0 1rem;
  display: flex;
  align-items: baseline;
  gap: 0.35rem;
}

.package-price strong {
  font-family: var(--font-display);
  font-size: 2rem;
  font-weight: 700;
  color: var(--accent-champagne);
}

.package-price span {
  font-size: 0.85rem;
  color: var(--text-muted);
}

.package-desc {
  margin: 0 0 1.25rem;
  color: var(--text-secondary);
  font-size: 0.92rem;
}

.package-features {
  margin: 0 0 1.65rem;
  padding: 0;
  list-style: none;
  display: grid;
  gap: 0.6rem;
  flex: 1;
}

.package-features li {
  position: relative;
  padding-left: 1.25rem;
  font-size: 0.88rem;
  color: var(--text-secondary);
}

.package-features li::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0.55em;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--accent-gold);
}

/* Interactive Estimator Section
   ========================================================================== */
.estimator-section {
  padding: 3rem 0 4rem;
  background: linear-gradient(180deg, rgba(18, 14, 12, 0.55) 0%, var(--bg-obsidian) 100%);
  border-top: 1px solid var(--border-subtle);
  border-bottom: 1px solid var(--border-subtle);
}

.estimator-card {
  display: grid;
  grid-template-columns: 1.25fr 1fr;
  gap: 2rem;
  padding: 2rem;
  border-radius: var(--radius-lg);
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
}

.estimator-controls {
  display: grid;
  gap: 1.35rem;
}

.range-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
}

.range-hint {
  font-size: 0.8rem;
  color: var(--accent-champagne);
}

.guest-input-row {
  display: grid;
  grid-template-columns: 1fr 96px;
  align-items: center;
  gap: 1rem;
}

.guest-input-row input[type="range"] {
  width: 100%;
  accent-color: var(--accent-gold);
  cursor: pointer;
}

.addons-fieldset {
  margin: 0;
  padding: 1.15rem;
  border-radius: var(--radius-md);
  border: 1px solid var(--border-subtle);
  background: var(--bg-espresso);
  display: grid;
  gap: 0.9rem;
}

.addons-fieldset legend {
  padding-inline: 0.45rem;
  font-size: 0.82rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--accent-champagne);
}

.addon-option {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  cursor: pointer;
}

.addon-option input[type="checkbox"] {
  margin-top: 0.25rem;
  width: 18px;
  height: 18px;
  accent-color: var(--accent-gold);
  flex-shrink: 0;
}

.addon-text {
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
}

.addon-text strong {
  font-size: 0.92rem;
  color: var(--text-primary);
}

.addon-text span {
  font-size: 0.82rem;
  color: var(--text-muted);
}

.estimator-summary {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 1.75rem;
  border-radius: var(--radius-md);
  background: var(--bg-espresso);
  border: 1px solid var(--border-strong);
}

.summary-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  margin-bottom: 1.25rem;
}

.summary-guests {
  font-size: 0.88rem;
  font-weight: 600;
  color: var(--text-secondary);
}

.summary-breakdown {
  margin: 0 0 1.5rem;
  display: grid;
  gap: 0.85rem;
}

.summary-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding-bottom: 0.75rem;
  border-bottom: 1px solid var(--border-subtle);
  font-size: 0.9rem;
}

.summary-row dt {
  color: var(--text-secondary);
}

.summary-row dd {
  margin: 0;
  font-weight: 600;
  color: var(--text-primary);
}

.summary-total-box {
  padding: 1.1rem 1.2rem;
  border-radius: var(--radius-md);
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  margin-bottom: 1.35rem;
}

.total-label {
  display: block;
  font-size: 0.76rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--text-muted);
}

.total-value {
  display: block;
  margin: 0.2rem 0;
  font-family: var(--font-display);
  font-size: clamp(2rem, 3vw, 2.5rem);
  font-weight: 700;
  line-height: 1.1;
  color: var(--accent-champagne);
}

.total-note {
  margin: 0;
  font-size: 0.82rem;
  color: var(--text-secondary);
}

.summary-cta {
  width: 100%;
}

/* Inquiry Form & Confirmation Section
   ========================================================================== */
.inquiry-section {
  padding: 4rem 0 4.5rem;
}

.inquiry-card {
  display: grid;
  grid-template-columns: 0.92fr 1.28fr;
  gap: 2.5rem;
  padding: 2.25rem;
  border-radius: var(--radius-lg);
  background: var(--bg-surface);
  border: 1px solid var(--border-strong);
  box-shadow: var(--shadow-luxury);
}

.inquiry-intro h2 {
  margin: 0 0 0.75rem;
  font-family: var(--font-display);
  font-size: clamp(1.9rem, 3.2vw, 2.5rem);
  font-weight: 600;
  line-height: 1.15;
}

.concierge-details {
  margin-top: 1.75rem;
  display: grid;
  gap: 1rem;
  padding-top: 1.5rem;
  border-top: 1px solid var(--border-subtle);
}

.detail-label {
  display: block;
  font-size: 0.74rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--accent-gold);
}

.detail-value {
  margin: 0.2rem 0 0;
  font-size: 0.95rem;
  color: var(--text-primary);
}

.recent-inquiries {
  margin-top: 1.5rem;
  padding: 1rem 1.1rem;
  border-radius: var(--radius-md);
  background: var(--bg-espresso);
  border: 1px solid var(--border-subtle);
}

.recent-heading {
  margin: 0 0 0.65rem;
  font-family: var(--font-display);
  font-size: 1.2rem;
  color: var(--accent-champagne);
}

.recent-list {
  margin: 0;
  padding: 0;
  list-style: none;
  display: grid;
  gap: 0.55rem;
}

.recent-item {
  display: flex;
  justify-content: space-between;
  gap: 0.75rem;
  font-size: 0.82rem;
  color: var(--text-secondary);
  padding-bottom: 0.45rem;
  border-bottom: 1px solid var(--border-subtle);
}

.recent-item:last-child {
  padding-bottom: 0;
  border-bottom: 0;
}

.recent-item strong {
  color: var(--text-primary);
}

.inquiry-form {
  display: grid;
  gap: 1.15rem;
}

.form-row {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1rem;
}

.form-field {
  display: grid;
  gap: 0.4rem;
}

.form-field label {
  font-size: 0.84rem;
  font-weight: 600;
  color: var(--text-secondary);
}

.form-field input[type="text"],
.form-field input[type="email"],
.form-field input[type="tel"],
.form-field input[type="date"],
.form-field input[type="number"],
.form-field select,
.form-field textarea {
  width: 100%;
  padding: 0.72rem 0.9rem;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-subtle);
  background: var(--bg-espresso);
  color: var(--text-primary);
  font-size: 0.92rem;
  transition: border-color var(--transition-fast);
}

.form-field input:focus,
.form-field select:focus,
.form-field textarea:focus {
  border-color: var(--accent-gold);
  outline: none;
}

.form-field.has-error input,
.form-field.has-error select,
.form-field.has-error textarea {
  border-color: var(--text-error);
}

.field-error {
  min-height: 1.1em;
  font-size: 0.78rem;
  color: var(--text-error);
}

.form-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  margin-top: 0.35rem;
}

.form-note {
  margin: 0;
  font-size: 0.78rem;
  color: var(--text-muted);
}

.form-note code {
  color: var(--accent-champagne);
}

.inquiry-confirmation {
  padding: 2rem;
  border-radius: var(--radius-md);
  background: var(--bg-espresso);
  border: 1px solid var(--accent-gold);
}

.inquiry-confirmation[hidden] {
  display: none;
}

.inquiry-confirmation h3 {
  margin: 0.85rem 0 0.5rem;
  font-family: var(--font-display);
  font-size: 2rem;
  color: var(--text-primary);
}

.confirm-copy {
  margin: 0 0 1.35rem;
  color: var(--text-secondary);
  font-size: 0.94rem;
}

.confirm-copy strong {
  color: var(--accent-champagne);
}

.confirm-summary {
  margin: 0 0 1.5rem;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.9rem;
  padding: 1.1rem;
  border-radius: var(--radius-sm);
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
}

.confirm-summary dt {
  font-size: 0.74rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-muted);
}

.confirm-summary dd {
  margin: 0.15rem 0 0;
  font-weight: 600;
  color: var(--text-primary);
}

/* SavorCart Drawer
   ========================================================================== */
.drawer-backdrop {
  position: fixed;
  inset: 0;
  z-index: 100;
  background: rgba(5, 4, 3, 0.72);
  backdrop-filter: blur(4px);
}

.drawer-backdrop[hidden] {
  display: none;
}

.cart-drawer {
  position: fixed;
  top: 0;
  right: 0;
  z-index: 110;
  width: min(420px, 100vw);
  height: 100vh;
  display: flex;
  flex-direction: column;
  background: var(--bg-espresso);
  border-left: 1px solid var(--border-strong);
  box-shadow: -16px 0 40px rgba(0, 0, 0, 0.65);
}

.cart-drawer[hidden] {
  display: none;
}

.cart-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  padding: 1.35rem 1.4rem;
  border-bottom: 1px solid var(--border-subtle);
}

.cart-header h2 {
  margin: 0;
  font-family: var(--font-display);
  font-size: 1.6rem;
  color: var(--text-primary);
}

.cart-subtitle {
  margin: 0.2rem 0 0;
  font-size: 0.8rem;
  color: var(--text-muted);
}

.cart-close {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  border: 1px solid var(--border-subtle);
  background: var(--bg-surface);
  color: var(--text-primary);
  font-size: 1.3rem;
  line-height: 1;
}

.cart-body {
  flex: 1;
  overflow-y: auto;
  padding: 1.25rem 1.4rem;
  display: flex;
  flex-direction: column;
  gap: 0.9rem;
}

.cart-empty {
  margin: auto 0;
  text-align: center;
  color: var(--text-muted);
  padding: 2rem 1rem;
}

.cart-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.85rem;
  padding: 0.9rem;
  border-radius: var(--radius-md);
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
}

.cart-item-info {
  min-width: 0;
}

.cart-item-title {
  margin: 0 0 0.2rem;
  font-weight: 600;
  font-size: 0.94rem;
  color: var(--text-primary);
}

.cart-item-price {
  margin: 0;
  font-size: 0.82rem;
  color: var(--accent-champagne);
}

.cart-item-controls {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  flex-shrink: 0;
}

.qty-btn,
.remove-btn {
  width: 28px;
  height: 28px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-subtle);
  background: var(--bg-elevated);
  color: var(--text-primary);
  font-weight: 700;
}

.qty-btn:hover,
.remove-btn:hover {
  border-color: var(--accent-gold);
  color: var(--accent-champagne);
}

.qty-value {
  min-width: 22px;
  text-align: center;
  font-size: 0.88rem;
  font-weight: 600;
}

.cart-footer {
  padding: 1.25rem 1.4rem 1.5rem;
  border-top: 1px solid var(--border-subtle);
  background: var(--bg-surface);
}

.cart-summary-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 1rem;
  font-size: 1rem;
}

.cart-summary-row strong {
  color: var(--accent-champagne);
  font-size: 1.15rem;
}

.cart-footer-actions {
  display: grid;
  grid-template-columns: 1fr 1.4fr;
  gap: 0.75rem;
}

/* Toast Notifications
   ========================================================================== */
.toast-container {
  position: fixed;
  right: 1.25rem;
  bottom: 1.25rem;
  z-index: 150;
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
  pointer-events: none;
}

.toast {
  padding: 0.8rem 1.15rem;
  border-radius: var(--radius-md);
  background: var(--bg-elevated);
  border: 1px solid var(--border-strong);
  color: var(--text-primary);
  font-size: 0.88rem;
  font-weight: 500;
  box-shadow: var(--shadow-luxury);
  animation: toastSlideIn 220ms ease-out forwards;
}

@keyframes toastSlideIn {
  from {
    opacity: 0;
    transform: translateY(10px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* Footer
   ========================================================================== */
.site-footer {
  background: var(--bg-espresso);
  border-top: 1px solid var(--border-subtle);
  padding: 3.5rem 0 1.75rem;
}

.footer-grid {
  display: grid;
  grid-template-columns: 1.5fr 1fr 1fr 1.1fr;
  gap: 2rem;
  margin-bottom: 2.5rem;
}

.footer-copy,
.footer-meta {
  color: var(--text-secondary);
  font-size: 0.88rem;
  margin: 0.75rem 0 0;
}

.footer-heading {
  margin: 0 0 0.9rem;
  font-family: var(--font-display);
  font-size: 1.22rem;
  color: var(--accent-champagne);
}

.footer-links {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 0.5rem;
}

.footer-links a {
  color: var(--text-secondary);
  font-size: 0.88rem;
  transition: color var(--transition-fast);
}

.footer-links a:hover {
  color: var(--accent-gold);
}

.footer-bottom {
  padding-top: 1.5rem;
  border-top: 1px solid var(--border-subtle);
  color: var(--text-muted);
  font-size: 0.82rem;
  text-align: center;
}

/* Responsive Breakpoints
   ========================================================================== */
@media (max-width: 1080px) {
  .nav-toggle {
    display: flex;
  }

  .primary-nav {
    position: fixed;
    top: 76px;
    left: 0;
    right: 0;
    background: var(--bg-espresso);
    border-bottom: 1px solid var(--border-strong);
    padding: 1.25rem 1.5rem;
    display: none;
  }

  .primary-nav.is-open {
    display: block;
  }

  .nav-list {
    flex-direction: column;
    align-items: flex-start;
    gap: 0.85rem;
  }

  .packages-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .estimator-card,
  .inquiry-card {
    grid-template-columns: 1fr;
    gap: 1.75rem;
  }

  .footer-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 760px) {
  .hero-metrics,
  .packages-grid,
  .form-row,
  .confirm-summary,
  .footer-grid {
    grid-template-columns: 1fr;
  }

  .hero-metrics {
    width: 100%;
  }

  .estimator-card,
  .inquiry-card {
    padding: 1.35rem;
  }

  .guest-input-row {
    grid-template-columns: 1fr;
  }
}

/* ==========================================================================
   SavorSpot — Catering & Private Events Interactivity (js/catering.js)
   ========================================================================== */

(function () {
  "use strict";

  const CART_STORAGE_KEY = "savorCart";
  const INQUIRIES_STORAGE_KEY = "savorCateringInquiries";

  const PACKAGES = {
    corporate: {
      name: "Corporate Luncheons",
      rate: 4800,
      minGuests: 15,
      maxGuests: 60,
      defaultGuests: 30
    },
    intimate: {
      name: "Intimate Dinners",
      rate: 7200,
      minGuests: 12,
      maxGuests: 40,
      defaultGuests: 28
    },
    grand: {
      name: "Grand Celebrations",
      rate: 9500,
      minGuests: 50,
      maxGuests: 250,
      defaultGuests: 100
    }
  };

  const navToggle = document.getElementById("navToggle");
  const primaryNav = document.getElementById("primaryNav");

  const packageCards = Array.from(document.querySelectorAll(".package-card"));
  const packageSelectBtns = Array.from(document.querySelectorAll("[data-select-package]"));

  const estPackage = document.getElementById("estPackage");
  const estGuestsRange = document.getElementById("estGuestsRange");
  const estGuestsInput = document.getElementById("estGuestsInput");
  const estRangeHint = document.getElementById("estRangeHint");
  const addonCheckboxes = [
    document.getElementById("optEspressoBar"),
    document.getElementById("optLiveGrill"),
    document.getElementById("optTableware")
  ].filter(Boolean);

  const estSummaryTier = document.getElementById("estSummaryTier");
  const estSummaryGuests = document.getElementById("estSummaryGuests");
  const estBaseRate = document.getElementById("estBaseRate");
  const estCountCopy = document.getElementById("estCountCopy");
  const estBaseTotal = document.getElementById("estBaseTotal");
  const estAddonsTotal = document.getElementById("estAddonsTotal");
  const estServiceFee = document.getElementById("estServiceFee");
  const estTotalCost = document.getElementById("estTotalCost");
  const estPerGuestAvg = document.getElementById("estPerGuestAvg");
  const applyEstimateBtn = document.getElementById("applyEstimateBtn");

  const inquiryForm = document.getElementById("cateringInquiryForm");
  const inquiryConfirmation = document.getElementById("inquiryConfirmation");
  const newInquiryBtn = document.getElementById("newInquiryBtn");

  const inqName = document.getElementById("inqName");
  const inqEmail = document.getElementById("inqEmail");
  const inqPhone = document.getElementById("inqPhone");
  const inqDate = document.getElementById("inqDate");
  const inqPackage = document.getElementById("inqPackage");
  const inqGuests = document.getElementById("inqGuests");
  const inqVenue = document.getElementById("inqVenue");
  const inqNotes = document.getElementById("inqNotes");

  const inqNameError = document.getElementById("inqNameError");
  const inqEmailError = document.getElementById("inqEmailError");
  const inqPhoneError = document.getElementById("inqPhoneError");
  const inqDateError = document.getElementById("inqDateError");
  const inqPackageError = document.getElementById("inqPackageError");
  const inqGuestsError = document.getElementById("inqGuestsError");

  const confirmName = document.getElementById("confirmName");
  const confirmRef = document.getElementById("confirmRef");
  const confirmPackage = document.getElementById("confirmPackage");
  const confirmGuests = document.getElementById("confirmGuests");
  const confirmDate = document.getElementById("confirmDate");
  const confirmEstimate = document.getElementById("confirmEstimate");

  const savedInquiriesCount = document.getElementById("savedInquiriesCount");
  const recentInquiriesWrap = document.getElementById("recentInquiriesWrap");
  const recentInquiriesList = document.getElementById("recentInquiriesList");

  const cartTrigger = document.getElementById("cartTrigger");
  const cartDrawer = document.getElementById("savorCart");
  const cartBackdrop = document.getElementById("cartBackdrop");
  const cartClose = document.getElementById("cartClose");
  const cartBadge = document.getElementById("cartBadge");
  const cartItemsContainer = document.getElementById("cartItemsContainer");
  const cartSubtotal = document.getElementById("cartSubtotal");
  const cartClearBtn = document.getElementById("cartClearBtn");
  const toastContainer = document.getElementById("toastContainer");

  let lastFocusedElement = null;

  /* ------------------------------------------------------------------------
     Utility Helpers
     ------------------------------------------------------------------------ */
  function formatPKR(amount) {
    return "PKR " + Math.round(Number(amount) || 0).toLocaleString("en-PK");
  }

  function showToast(message) {
    if (!toastContainer) return;
    const toast = document.createElement("div");
    toast.className = "toast";
    toast.textContent = message;
    toastContainer.appendChild(toast);

    window.setTimeout(function () {
      toast.remove();
    }, 3200);
  }

  function clampGuests(val) {
    const parsed = parseInt(val, 10);
    if (Number.isNaN(parsed)) return 10;
    return Math.max(10, Math.min(250, parsed));
  }

  /* ------------------------------------------------------------------------
     Mobile Navigation Toggle
     ------------------------------------------------------------------------ */
  if (navToggle && primaryNav) {
    navToggle.addEventListener("click", function () {
      const expanded = navToggle.getAttribute("aria-expanded") === "true";
      navToggle.setAttribute("aria-expanded", String(!expanded));
      primaryNav.classList.toggle("is-open", !expanded);
    });
  }

  /* ------------------------------------------------------------------------
     Dynamic Catering Cost Estimator
     ------------------------------------------------------------------------ */
  function getEstimatorState() {
    const pkgKey = estPackage && PACKAGES[estPackage.value] ? estPackage.value : "intimate";
    const pkg = PACKAGES[pkgKey];
    const guests = clampGuests(estGuestsInput ? estGuestsInput.value : pkg.defaultGuests);

    let addonsTotal = 0;
    const selectedAddons = [];

    addonCheckboxes.forEach(function (box) {
      if (!box.checked) return;
      const cost = Number(box.dataset.cost) || 0;
      const type = box.dataset.type || "flat";
      addonsTotal += type === "per-guest" ? cost * guests : cost;
      const label = box.closest(".addon-option")?.querySelector("strong")?.textContent || "";
      if (label) selectedAddons.push(label);
    });

    const baseTotal = pkg.rate * guests;
    const subtotal = baseTotal + addonsTotal;
    const serviceFee = Math.round(subtotal * 0.1);
    const total = subtotal + serviceFee;

    return {
      pkgKey: pkgKey,
      pkg: pkg,
      guests: guests,
      baseTotal: baseTotal,
      addonsTotal: addonsTotal,
      serviceFee: serviceFee,
      total: total,
      perGuestAvg: Math.round(total / guests),
      selectedAddons: selectedAddons
    };
  }

  function updateEstimatorUI() {
    const state = getEstimatorState();

    packageCards.forEach(function (card) {
      card.classList.toggle("is-selected", card.dataset.package === state.pkgKey);
    });

    if (estRangeHint) {
      const inRange =
        state.guests >= state.pkg.minGuests && state.guests <= state.pkg.maxGuests;
      estRangeHint.textContent = inRange
        ? "Recommended: " + state.pkg.minGuests + " – " + state.pkg.maxGuests + " guests"
        : "Outside typical " + state.pkg.minGuests + "–" + state.pkg.maxGuests + " range (custom quote)";
    }

    if (estSummaryTier) estSummaryTier.textContent = state.pkg.name;
    if (estSummaryGuests) estSummaryGuests.textContent = state.guests + " Guests";
    if (estBaseRate) estBaseRate.textContent = formatPKR(state.pkg.rate);
    if (estCountCopy) estCountCopy.textContent = String(state.guests);
    if (estBaseTotal) estBaseTotal.textContent = formatPKR(state.baseTotal);
    if (estAddonsTotal) estAddonsTotal.textContent = formatPKR(state.addonsTotal);
    if (estServiceFee) estServiceFee.textContent = formatPKR(state.serviceFee);
    if (estTotalCost) estTotalCost.textContent = formatPKR(state.total);
    if (estPerGuestAvg) {
      estPerGuestAvg.textContent =
        "Approx. " + formatPKR(state.perGuestAvg) + " per guest incl. service";
    }
  }

  function selectPackageForEstimator(pkgKey) {
    if (!PACKAGES[pkgKey] || !estPackage) return;
    estPackage.value = pkgKey;
    const defaultCount = PACKAGES[pkgKey].defaultGuests;
    if (estGuestsRange) estGuestsRange.value = String(defaultCount);
    if (estGuestsInput) estGuestsInput.value = String(defaultCount);
    updateEstimatorUI();
  }

  packageSelectBtns.forEach(function (btn) {
    btn.addEventListener("click", function () {
      const pkgKey = btn.dataset.selectPackage;
      selectPackageForEstimator(pkgKey);
      const estimatorEl = document.getElementById("estimatorSection");
      if (estimatorEl) {
        estimatorEl.scrollIntoView({ behavior: "smooth", block: "start" });
      }
      showToast("Loaded " + PACKAGES[pkgKey].name + " into the estimator.");
    });
  });

  if (estPackage) {
    estPackage.addEventListener("change", function () {
      updateEstimatorUI();
    });
  }

  if (estGuestsRange && estGuestsInput) {
    estGuestsRange.addEventListener("input", function () {
      estGuestsInput.value = estGuestsRange.value;
      updateEstimatorUI();
    });

    estGuestsInput.addEventListener("input", function () {
      const clamped = clampGuests(estGuestsInput.value);
      estGuestsRange.value = String(clamped);
      updateEstimatorUI();
    });

    estGuestsInput.addEventListener("blur", function () {
      const clamped = clampGuests(estGuestsInput.value);
      estGuestsInput.value = String(clamped);
      estGuestsRange.value = String(clamped);
      updateEstimatorUI();
    });
  }

  addonCheckboxes.forEach(function (box) {
    box.addEventListener("change", updateEstimatorUI);
  });

  if (applyEstimateBtn) {
    applyEstimateBtn.addEventListener("click", function () {
      const state = getEstimatorState();
      if (inqPackage) inqPackage.value = state.pkgKey;
      if (inqGuests) inqGuests.value = String(state.guests);
      if (inqNotes && state.selectedAddons.length && !inqNotes.value.trim()) {
        inqNotes.value = "Requested enhancements: " + state.selectedAddons.join(", ") + ".";
      }

      if (inquiryConfirmation && !inquiryConfirmation.hidden && inquiryForm) {
        inquiryConfirmation.hidden = true;
        inquiryForm.hidden = false;
      }

      const inquirySection = document.getElementById("inquirySection");
      if (inquirySection) {
        inquirySection.scrollIntoView({ behavior: "smooth", block: "start" });
      }
      showToast("Applied " + state.pkg.name + " (" + state.guests + " guests) to your inquiry.");
    });
  }

  /* ------------------------------------------------------------------------
     Catering Inquiry Storage, Validation & Confirmation
     ------------------------------------------------------------------------ */
  function readStoredInquiries() {
    try {
      const raw = window.localStorage.getItem(INQUIRIES_STORAGE_KEY);
      if (!raw) return [];
      const parsed = JSON.parse(raw);
      return Array.isArray(parsed) ? parsed : [];
    } catch (_err) {
      return [];
    }
  }

  function writeStoredInquiries(inquiries) {
    try {
      window.localStorage.setItem(INQUIRIES_STORAGE_KEY, JSON.stringify(inquiries));
      return true;
    } catch (_err) {
      showToast("Unable to save inquiry in local storage.");
      return false;
    }
  }

  function renderSavedInquiries() {
    const stored = readStoredInquiries();
    if (savedInquiriesCount) {
      savedInquiriesCount.textContent =
        stored.length === 1
          ? "1 inquiry saved locally"
          : stored.length + " inquiries saved locally";
    }

    if (!recentInquiriesWrap || !recentInquiriesList) return;
    recentInquiriesList.innerHTML = "";

    if (!stored.length) {
      recentInquiriesWrap.hidden = true;
      return;
    }

    recentInquiriesWrap.hidden = false;
    stored.slice(0, 3).forEach(function (entry) {
      const li = document.createElement("li");
      li.className = "recent-item";

      const left = document.createElement("span");
      const strong = document.createElement("strong");
      strong.textContent = entry.packageName;
      left.appendChild(strong);
      left.appendChild(document.createTextNode(" • " + entry.guests + " guests"));

      const right = document.createElement("span");
      right.textContent = formatPKR(entry.estimatedTotal);

      li.appendChild(left);
      li.appendChild(right);
      recentInquiriesList.appendChild(li);
    });
  }

  function setFieldError(inputEl, errorEl, message) {
    if (errorEl) errorEl.textContent = message || "";
    if (!inputEl) return;
    const wrapper = inputEl.closest(".form-field");
    if (wrapper) {
      wrapper.classList.toggle("has-error", Boolean(message));
    }
  }

  function clearInquiryErrors() {
    setFieldError(inqName, inqNameError, "");
    setFieldError(inqEmail, inqEmailError, "");
    setFieldError(inqPhone, inqPhoneError, "");
    setFieldError(inqDate, inqDateError, "");
    setFieldError(inqPackage, inqPackageError, "");
    setFieldError(inqGuests, inqGuestsError, "");
  }

  function setMinEventDate() {
    if (!inqDate) return;
    const today = new Date();
    const yyyy = today.getFullYear();
    const mm = String(today.getMonth() + 1).padStart(2, "0");
    const dd = String(today.getDate()).padStart(2, "0");
    inqDate.min = yyyy + "-" + mm + "-" + dd;
  }

  if (inquiryForm) {
    inquiryForm.addEventListener("submit", function (event) {
      event.preventDefault();
      clearInquiryErrors();

      const name = inqName ? inqName.value.trim() : "";
      const email = inqEmail ? inqEmail.value.trim() : "";
      const phone = inqPhone ? inqPhone.value.trim() : "";
      const eventDate = inqDate ? inqDate.value : "";
      const pkgKey = inqPackage ? inqPackage.value : "";
      const guests = parseInt(inqGuests ? inqGuests.value : "0", 10);
      const venue = inqVenue ? inqVenue.value.trim() : "";
      const notes = inqNotes ? inqNotes.value.trim() : "";

      let isValid = true;

      if (name.length < 2) {
        setFieldError(inqName, inqNameError, "Please enter at least 2 characters for your name.");
        isValid = false;
      }

      if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
        setFieldError(inqEmail, inqEmailError, "Please enter a valid email address.");
        isValid = false;
      }

      if (phone.replace(/\D/g, "").length < 7) {
        setFieldError(inqPhone, inqPhoneError, "Please enter a valid contact phone number.");
        isValid = false;
      }

      if (!eventDate) {
        setFieldError(inqDate, inqDateError, "Please choose a preferred event date.");
        isValid = false;
      }

      if (!pkgKey || !PACKAGES[pkgKey]) {
        setFieldError(inqPackage, inqPackageError, "Please select a catering package.");
        isValid = false;
      }

      if (Number.isNaN(guests) || guests < 10 || guests > 250) {
        setFieldError(inqGuests, inqGuestsError, "Guest count must be between 10 and 250.");
        isValid = false;
      }

      if (!isValid) return;

      const selectedPkg = PACKAGES[pkgKey];
      const estState = getEstimatorState();
      const addonsForQuote = pkgKey === estState.pkgKey ? estState.addonsTotal : 0;
      const baseForQuote = selectedPkg.rate * guests;
      const estimatedTotal = Math.round((baseForQuote + addonsForQuote) * 1.1);
      const refCode = "SS-CAT-" + String(Date.now()).slice(-4);

      const inquiryRecord = {
        id: refCode,
        name: name,
        email: email,
        phone: phone,
        eventDate: eventDate,
        packageKey: pkgKey,
        packageName: selectedPkg.name,
        guests: guests,
        venue: venue || "To be confirmed",
        notes: notes,
        estimatedTotal: estimatedTotal,
        createdAt: new Date().toISOString()
      };

      const existing = readStoredInquiries();
      existing.unshift(inquiryRecord);
      writeStoredInquiries(existing);
      renderSavedInquiries();

      if (confirmName) confirmName.textContent = name;
      if (confirmRef) confirmRef.textContent = refCode;
      if (confirmPackage) confirmPackage.textContent = selectedPkg.name;
      if (confirmGuests) confirmGuests.textContent = guests + " Guests";
      if (confirmDate) confirmDate.textContent = eventDate;
      if (confirmEstimate) confirmEstimate.textContent = formatPKR(estimatedTotal);

      inquiryForm.hidden = true;
      if (inquiryConfirmation) inquiryConfirmation.hidden = false;

      showToast("Catering inquiry " + refCode + " submitted.");
    });
  }

  if (newInquiryBtn && inquiryForm && inquiryConfirmation) {
    newInquiryBtn.addEventListener("click", function () {
      inquiryForm.reset();
      if (inqGuests) inqGuests.value = "28";
      inquiryConfirmation.hidden = true;
      inquiryForm.hidden = false;
      if (inqName) inqName.focus();
    });
  }

  /* ------------------------------------------------------------------------
     Shared "savorCart" Drawer & localStorage Sync
     ------------------------------------------------------------------------ */
  function readCart() {
    try {
      const raw = window.localStorage.getItem(CART_STORAGE_KEY);
      if (!raw) return [];
      const parsed = JSON.parse(raw);
      return Array.isArray(parsed) ? parsed : [];
    } catch (_err) {
      return [];
    }
  }

  function writeCart(items) {
    try {
      window.localStorage.setItem(CART_STORAGE_KEY, JSON.stringify(items));
    } catch (_err) {
      showToast("Unable to save order in local storage.");
    }
    renderCart();
  }

  function updateItemQty(id, delta) {
    const cart = readCart();
    const updated = cart
      .map(function (entry) {
        if (entry.id !== id) return entry;
        return {
          id: entry.id,
          title: entry.title,
          price: entry.price,
          qty: (Number(entry.qty) || 1) + delta
        };
      })
      .filter(function (entry) {
        return entry.qty > 0;
      });

    writeCart(updated);
  }

  function renderCart() {
    const cart = readCart();
    const totalCount = cart.reduce(function (sum, item) {
      return sum + (Number(item.qty) || 1);
    }, 0);
    const subtotalAmount = cart.reduce(function (sum, item) {
      return sum + (Number(item.price) || 0) * (Number(item.qty) || 1);
    }, 0);

    if (cartBadge) {
      cartBadge.textContent = String(totalCount);
    }
    if (cartSubtotal) {
      cartSubtotal.textContent = formatPKR(subtotalAmount);
    }

    if (!cartItemsContainer) return;
    cartItemsContainer.innerHTML = "";

    if (!cart.length) {
      const emptyEl = document.createElement("p");
      emptyEl.className = "cart-empty";
      emptyEl.textContent =
        "Your order drawer is currently empty. Add signature plates, elixirs, or desserts from the gallery or menu.";
      cartItemsContainer.appendChild(emptyEl);
      return;
    }

    cart.forEach(function (item) {
      const row = document.createElement("div");
      row.className = "cart-item";

      const info = document.createElement("div");
      info.className = "cart-item-info";

      const title = document.createElement("p");
      title.className = "cart-item-title";
      title.textContent = item.title;

      const price = document.createElement("p");
      price.className = "cart-item-price";
      price.textContent = formatPKR(item.price);

      info.appendChild(title);
      info.appendChild(price);

      const controls = document.createElement("div");
      controls.className = "cart-item-controls";

      const decBtn = document.createElement("button");
      decBtn.type = "button";
      decBtn.className = "qty-btn";
      decBtn.textContent = "−";
      decBtn.setAttribute("aria-label", "Decrease quantity of " + item.title);
      decBtn.addEventListener("click", function () {
        updateItemQty(item.id, -1);
      });

      const qtyVal = document.createElement("span");
      qtyVal.className = "qty-value";
      qtyVal.textContent = String(item.qty || 1);

      const incBtn = document.createElement("button");
      incBtn.type = "button";
      incBtn.className = "qty-btn";
      incBtn.textContent = "+";
      incBtn.setAttribute("aria-label", "Increase quantity of " + item.title);
      incBtn.addEventListener("click", function () {
        updateItemQty(item.id, 1);
      });

      const removeBtn = document.createElement("button");
      removeBtn.type = "button";
      removeBtn.className = "remove-btn";
      removeBtn.textContent = "×";
      removeBtn.setAttribute("aria-label", "Remove " + item.title + " from order");
      removeBtn.addEventListener("click", function () {
        updateItemQty(item.id, -(Number(item.qty) || 1));
      });

      controls.appendChild(decBtn);
      controls.appendChild(qtyVal);
      controls.appendChild(incBtn);
      controls.appendChild(removeBtn);

      row.appendChild(info);
      row.appendChild(controls);
      cartItemsContainer.appendChild(row);
    });
  }

  function openCartDrawer() {
    if (!cartDrawer || !cartBackdrop) return;
    lastFocusedElement = document.activeElement;
    cartDrawer.hidden = false;
    cartBackdrop.hidden = false;
    if (cartTrigger) cartTrigger.setAttribute("aria-expanded", "true");
    document.body.style.overflow = "hidden";
    if (cartClose) cartClose.focus();
  }

  function closeCartDrawer() {
    if (!cartDrawer || !cartBackdrop || cartDrawer.hidden) return;
    cartDrawer.hidden = true;
    cartBackdrop.hidden = true;
    if (cartTrigger) cartTrigger.setAttribute("aria-expanded", "false");
    document.body.style.overflow = "";
    if (lastFocusedElement && typeof lastFocusedElement.focus === "function") {
      lastFocusedElement.focus();
    }
  }

  if (cartTrigger) {
    cartTrigger.addEventListener("click", openCartDrawer);
  }
  if (cartClose) {
    cartClose.addEventListener("click", closeCartDrawer);
  }
  if (cartBackdrop) {
    cartBackdrop.addEventListener("click", closeCartDrawer);
  }
  if (cartClearBtn) {
    cartClearBtn.addEventListener("click", function () {
      writeCart([]);
      showToast("Cleared your SavorSpot order.");
    });
  }

  /* ------------------------------------------------------------------------
     Global Keyboard & Cross-Tab Storage Listeners
     ------------------------------------------------------------------------ */
  document.addEventListener("keydown", function (event) {
    if (cartDrawer && !cartDrawer.hidden && event.key === "Escape") {
      closeCartDrawer();
    }
  });

  window.addEventListener("storage", function (event) {
    if (event.key === CART_STORAGE_KEY) {
      renderCart();
    } else if (event.key === INQUIRIES_STORAGE_KEY) {
      renderSavedInquiries();
    }
  });

  // Initial setup on load
  setMinEventDate();
  updateEstimatorUI();
  renderSavedInquiries();
  renderCart();
})();

args.CommandLine:
if (Get-Command node -ErrorAction SilentlyContinue) {
  node --check js/catering.js
  node --check js/gallery.js
  node --check js/chefs-reviews.js
  Write-Host "Node syntax check passed."
} else {
  Write-Host "Node not found, skipping node --check."
}

$pages = @("pages/gallery.html", "pages/chefs-reviews.html", "pages/catering.html")
$expectedNav = @("../index.html", "menu.html", "deals.html", "reservations.html", "gallery.html", "chefs-reviews.html", "catering.html", "about.html", "contact.html")
$sharedIds = @("siteHeader", "navToggle", "primaryNav", "cartTrigger", "cartBadge", "cartBackdrop", "savorCart", "cartClose", "cartItemsContainer", "cartSubtotal", "cartClearBtn", "cartCheckoutBtn", "toastContainer")

foreach ($p in $pages) {
  $content = Get-Content -Raw $p
  if ($content -match "(?i)lorem\s+ipsum") {
    Write-Error "Lorem ipsum found in $p"
  }
  foreach ($href in $expectedNav) {
    if ($content -notmatch [regex]::Escape("href=`"$href`"")) {
      Write-Error "Missing nav/link href=$href in $p"
    }
  }
  foreach ($id in $sharedIds) {
    if ($content -notmatch [regex]::Escape("id=`"$id`"")) {
      Write-Error "Missing shared ID id=$id in $p"
    }
  }
}

$catHtml = Get-Content -Raw "pages/catering.html"
$catJs = Get-Content -Raw "js/catering.js"
$idMatches = [regex]::Matches($catJs, 'getElementById\("([^"]+)"\)')
$missingIds = @()
foreach ($m in $idMatches) {
  $id = $m.Groups[1].Value
  if ($catHtml -notmatch [regex]::Escape("id=`"$id`"")) {
    $missingIds += $id
  }
}
if ($missingIds.Count -gt 0) {
  Write-Error ("Missing IDs in catering.html: " + ($missingIds -join ", "))
} else {
  Write-Host "All getElementById references in js/catering.js verified in pages/catering.html."
}

# Check CSS & JS relative paths in catering.html
if (Test-Path "css/catering.css") { Write-Host "css/catering.css exists." } else { Write-Error "Missing css/catering.css" }
if (Test-Path "js/catering.js") { Write-Host "js/catering.js exists." } else { Write-Error "Missing js/catering.js" }
Write-Host "Cross-page consistency check complete."
